import{_ as t,o as n,c as r,ak as s}from"./chunks/framework.sV-XtlWr.js";const f=JSON.parse(`{"title":"Runs from the editor","description":"Run Playwright tests from VS Code or a JetBrains IDE and follow the run in the status bar: the editor reads its results within a second of its end, lays them over the latest CI run's failures in a tree, and says when a run never reached the instance.","frontmatter":{"title":"Runs from the editor","description":"Run Playwright tests from VS Code or a JetBrains IDE and follow the run in the status bar: the editor reads its results within a second of its end, lays them over the latest CI run's failures in a tree, and says when a run never reached the instance.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-runs.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-runs.html"}],["meta",{"property":"og:title","content":"Runs from the editor | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Run Playwright tests from VS Code or a JetBrains IDE and follow the run in the status bar: the editor reads its results within a second of its end, lays them over the latest CI run's failures in a tree, and says when a run never reached the instance."}]]},"headers":[],"relativePath":"features/editor-runs.md","filePath":"features/editor-runs.md","lastUpdated":1791472228000}`),a={name:"features/editor-runs.md"};function i(o,e,h,l,d,u){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="runs-from-the-editor" tabindex="-1">Runs from the editor <a class="header-anchor" href="#runs-from-the-editor" aria-label="Permalink to &quot;Runs from the editor&quot;">​</a></h1><p>The <a href="./editors.html">editor extensions</a> run your tests where you edit them, then show what the run changed: its progress in the status bar while it executes, and its results over the latest CI run&#39;s failures within a second of its end.</p><h2 id="run-tests" tabindex="-1">Run tests <a class="header-anchor" href="#run-tests" aria-label="Permalink to &quot;Run tests&quot;">​</a></h2><ul><li>The lines above a locator line, an application file or a page file (CodeLens in VS Code, Code Vision in a JetBrains IDE) run the tests they name when clicked.</li><li><strong>Piwi: Run the tests that reach this file</strong> runs every test that reaches the active file through <a href="/features/code-reach.html">code reach</a>; it is also in the editor&#39;s context menu.</li><li><strong>Piwi: Run selection…</strong> runs one of the project&#39;s saved <a href="/features/test-selection.html">selections</a>.</li></ul><p>The command is the one <code>piwi run</code> would build, run from the Playwright config&#39;s folder: in a terminal in VS Code, in the Run tool window in a JetBrains IDE, whose <strong>Rerun</strong> starts it again. It sets <code>PIWI_ORIGIN=editor</code> and a <code>PIWI_ORIGIN_REF</code> of its own (<a href="/reference/test-metadata.html#run-origin">run origin</a>), by which the editor finds its run on the instance. The editor&#39;s breakpoints pause it in the browser, with Piwi&#39;s picker one click away: <a href="./editor-breakpoints.html">Breakpoints in the browser</a>.</p><h2 id="your-local-runs" tabindex="-1">Your local runs <a class="header-anchor" href="#your-local-runs" aria-label="Permalink to &quot;Your local runs&quot;">​</a></h2><p>A later finished run on the branch, from the editor, <code>piwi run</code>, <code>npx playwright test</code> or the desktop app, overlays the latest CI run per test and Playwright project: a test it fixed leaves the Problems panel, its lens saying <em>fixed locally in run #124</em>; a test failing in it is an error labeled <em>local run #124</em>, or <em>your run #124</em> when this editor started it.</p><h2 id="after-a-run" tabindex="-1">After a run <a class="header-anchor" href="#after-a-run" aria-label="Permalink to &quot;After a run&quot;">​</a></h2><p>The editor listens to the instance&#39;s event stream: within a second of a run of the project ending, it reads the branch&#39;s latest run and its failures again. While the stream is connected, it also reads them every five minutes, for an instance scaled out without sticky sessions; without the stream, such as behind a proxy that buffers it, every minute.</p><p>A run started from the editor is its own wherever it runs: the status bar follows it as it runs, and its failures read <em>your run #124</em> once it ends. When the command ends and no run on the instance carries its ref, the editor says so: <code>The run ended (exit code 1) but did not reach https://piwi.example.com: is the Piwi reporter in the Playwright config?</code> VS Code learns that a command ended through shell integration (1.93 and later), and gives each run a terminal of its own; without it, a folder&#39;s runs share one terminal, and a run that never arrived goes unmentioned.</p><h2 id="when-your-run-ends" tabindex="-1">When your run ends <a class="header-anchor" href="#when-your-run-ends" aria-label="Permalink to &quot;When your run ends&quot;">​</a></h2><p>Once a run you started from the editor ends and the editor has read it, a notification (a balloon in a JetBrains IDE) says what it changed: <code>Piwi: run #124 · 1 of 3 CI failures fixed, 2 still failing (login.spec.ts › logs in, checkout.spec.ts › pays)</code>, then the tests it failed that were not failing before. It offers <strong>Open the failures</strong>, <strong>Open in dashboard</strong> and, when something fails, <strong>Re-run failing</strong>. The <code>piwi.runNotifications</code> setting (<strong>Settings → Tools → Piwi</strong> in a JetBrains IDE) shows it always, only when something fails, or never.</p><p>While the run executes, the gutter follows it: a test shows as running when it begins, then its result once it ends.</p><h2 id="failures-follow-your-edits" tabindex="-1">Failures follow your edits <a class="header-anchor" href="#failures-follow-your-edits" aria-label="Permalink to &quot;Failures follow your edits&quot;">​</a></h2><p>A run reports the line a test failed at in the files it ran. The editor reads those files as the run saw them and follows each failing line through your changes, saved or not:</p><ul><li>Add or remove lines above a failing line, and its error moves with it: in the Problems panel, in the lines above the test, in the Piwi tool window of a JetBrains IDE.</li><li>Rewrite the failing line, and the error turns into an information marker, <em>Edited since run #120: …</em>: the run said nothing about the new line. <strong>Run this test</strong> comes first among its quick fixes, and the reason above the line reads <em>✎ edited since run #120</em>. The test keeps its failing mark until a run says otherwise.</li><li>Delete the test, and its failure leaves the editor.</li></ul><p>The next run that covers the test says what is true: a failure there is an error again, and a pass takes it away.</p><p>For a CI run, the files as the run saw them are those of the run&#39;s commit (<code>git show</code>). For a run on your machine, which ran your files as saved, a run that recorded no commit, or a commit your clone does not have, they are the files as saved when the editor first showed the failure.</p><h2 id="the-failures-view" tabindex="-1">The failures view <a class="header-anchor" href="#the-failures-view" aria-label="Permalink to &quot;The failures view&quot;">​</a></h2><p>The latest run&#39;s failures as a tree: the <strong>Failures</strong> view of the <strong>Piwi</strong> panel in VS Code, the Piwi tool window in a JetBrains IDE. Its first node is the run, <code>Run #120 · CI · feature/x · 3 failing · 1 fixed locally</code>, with its age, or the progress of the run you started (<code>running 4/9</code>). Under it:</p><ul><li><strong>Your runs since</strong> lists the runs laid over it, such as <code>#124 · your run · 2 min ago · 1 passed, 0 failed</code>; a click opens one in the dashboard.</li><li>The failures, grouped by spec (the default), by <a href="/features/failure-clusters.html">failure cluster</a>, by owner, or flat: <strong>Group by…</strong> in the view&#39;s title bar, the toggles of the tool window&#39;s toolbar. The choice is kept for the workspace, and each group counts its failures.</li><li>A failure shows its title, where it failed (<code>tests/login.spec.ts:42 · chromium · new</code>), and an icon for failing, edited since the run, or fixed locally, with the headline and its run (<code>your run #124</code>, <code>edited since run #120</code>).</li></ul><p>Click a failure (double-click or Enter in a JetBrains IDE) to open its line. <strong>Run this test</strong>, <strong>Open the trace</strong> and <strong>Open in dashboard</strong> sit on its row in VS Code; the context menu adds <strong>Open the screenshot</strong>, <strong>Copy context for agent</strong>, and, on a CI failure while the <a href="/features/desktop.html#jobs-from-your-editor">desktop app</a> runs, <strong>Reproduce in the desktop app</strong> and <strong>Find the breaking commit in the desktop app</strong>. <strong>Heal</strong> stays a quick fix on the line.</p><p>The title bar, or the toolbar, holds Refresh, <strong>Re-run the failing tests</strong>, <strong>Open the run in the dashboard</strong>, <strong>Compare with…</strong> and the grouping. In VS Code, <strong>Follow the active editor</strong> selects the first failure of the file you switch to, and the badge counts the failing tests, as the tool window&#39;s title does. The tree is read again when a run ends or an edit moves a failure. The Problems panel keeps its errors.</p><h2 id="compare-with-another-run" tabindex="-1">Compare with another run <a class="header-anchor" href="#compare-with-another-run" aria-label="Permalink to &quot;Compare with another run&quot;">​</a></h2><p>By default, failures are read against the checked-out branch&#39;s latest complete run, else the default branch&#39;s. <strong>Piwi: Compare with…</strong> (<strong>Tools → Piwi → Compare With…</strong> in a JetBrains IDE, and the failures view&#39;s title bar) chooses another run to compare with: a branch&#39;s latest complete run, a run by its id, or <strong>My local runs only</strong>, your runs from this machine, the desktop app or an editor, without CI. Your runs since are laid over each. The status bar tooltip and the failures view name it (<code>Baseline: CI run #120 on feature/x</code>), ending with <code>(no run)</code> when it found none. The choice is kept on this machine, per Playwright config.</p><h2 id="re-run-the-failing-tests" tabindex="-1">Re-run the failing tests <a class="header-anchor" href="#re-run-the-failing-tests" aria-label="Permalink to &quot;Re-run the failing tests&quot;">​</a></h2><p><strong>Piwi: Re-run the failing tests</strong> (<strong>Tools → Piwi → Re-run the Failing Tests</strong>) runs every test still failing, or edited since its run, in one command; when none fails, it says so. <strong>Run this test</strong> also sits above the reason line of a failing test, beside <strong>Screenshot</strong> and <strong>Trace</strong>.</p><h2 id="the-status-bar" tabindex="-1">The status bar <a class="header-anchor" href="#the-status-bar" aria-label="Permalink to &quot;The status bar&quot;">​</a></h2><p>The latest complete run on the branch: how many tests passed, failed and were flaky, or what still fails and what your local runs fixed (<code>2 failing · 1 fixed locally</code>). While a run started from this editor, or another run of the branch, is in progress, the item counts it instead (<code>4/9 · 1 failing · your run</code>) and returns to the latest run when it ends.</p><p>Click it to read the latest run and its failures again (<strong>Piwi: Refresh the latest run</strong>), without the indexes <strong>Piwi: Refresh</strong> fetches. The tooltip holds the run&#39;s counts, the baseline, your local runs since, the run in progress, and when the run was read (<code>Updated 12 s ago · live</code> while the event stream is connected, <code>· read every minute</code> without it). In VS Code it ends with <strong>Open run #120</strong>, <strong>Open in dashboard</strong>, <strong>Compare with…</strong> and <strong>Connect</strong>; in a JetBrains IDE, <strong>Tools → Piwi → Open the Latest Run in the Dashboard</strong>, also in the Piwi tool window&#39;s toolbar, opens the run. When the extension is not connected, the item says why, and a click runs <strong>Piwi: Connect</strong>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editors.html">Editor extensions</a>: the failures, lenses and quick fixes the editor shows from your suite.</li><li><a href="./editor-connection.html">Editor connection</a>: the instance the editor reads, and its key.</li><li><a href="/features/test-selection.html">Test selection</a>: the saved selections <strong>Run selection…</strong> runs.</li></ul>',32)])])}const g=t(a,[["render",i]]);export{f as __pageData,g as default};
